public class GalleryLabActivity extends Activity{
@Override protected void onCreate(Bundle b){super.onCreate(b);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(dp(20),dp(28),dp(20),dp(20));r.setBackgroundColor(Color.rgb(247,245,239));r.addView(t("AIRI Gallery AI",28,true));TextView s=t("Photo tools untuk Realme 3 Pro",13,false);s.setTextColor(Color.DKGRAY);r.addView(s,lp(-1,-2,0,2,0,18));add(r,"Smart Eraser","Bersihkan objek kecil",SmartEraserActivity.class);add(r,"Visual Search","Cari berdasarkan gambar",CircleSearchActivity.class);add(r,"Wallpaper Studio","Buat wallpaper AIRI",WallpaperLabActivity.class);TextView open=btn("Buka Galeri");open.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_VIEW);i.setType("image/*");try{startActivity(i);}catch(Exception ignored){}});r.addView(open,lp(-1,dp(50),0,14,0,0));setContentView(r);}
private void add(LinearLayout r,String a,String b,Class<?> c){LinearLayout x=new LinearLayout(this);x.setOrientation(LinearLayout.VERTICAL);x.setPadding(dp(16),dp(14),dp(16),dp(14));android.graphics.drawable.GradientDrawable d=new android.graphics.drawable.GradientDrawable();d.setColor(Color.WHITE);d.setCornerRadius(dp(20));d.setStroke(dp(1),Color.rgb(226,225,220));x.setBackground(d);x.addView(t(a,16,true));TextView s=t(b,12,false);s.setTextColor(Color.GRAY);x.addView(s);x.setOnClickListener(v->startActivity(new Intent(this,c)));r.addView(x,lp(-1,dp(76),0,0,0,8));}
private TextView t(String s,float z,boolean b){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(Color.rgb(25,29,32));v.setTypeface(android.graphics.Typeface.create("sans",b?1:0));return v;}private TextView btn(String s){TextView v=t(s,14,true);v.setTextColor(Color.WHITE);v.setGravity(Gravity.CENTER);android.graphics.drawable.GradientDrawable d=new android.graphics.drawable.GradientDrawable();d.setColor(Color.rgb(48,86,117));d.setCornerRadius(dp(24));v.setBackground(d);return v;}private LinearLayout.LayoutParams lp(int w,int h,int l,int t,int rr,int b){int ww=w==-1?ViewGroup.LayoutParams.MATCH_PARENT:(w==-2?ViewGroup.LayoutParams.WRAP_CONTENT:w),hh=h==-1?ViewGroup.LayoutParams.MATCH_PARENT:(h==-2?ViewGroup.LayoutParams.WRAP_CONTENT:h);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(ww,hh);p.setMargins(dp(l),dp(t),dp(rr),dp(b));return p;}private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}}
